"use strict";(self.webpackChunk_=self.webpackChunk_||[]).push([["266"],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/getting-started/local-setup","label":"Local Setup","docId":"getting-started/local-setup","unlisted":false}],"href":"/docs/category/getting-started"},{"type":"category","label":"Architecture","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/architecture/overview","label":"System Overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/docs/architecture/node-model","label":"Node Model & Feature Registration","docId":"architecture/node-model","unlisted":false},{"type":"link","href":"/docs/architecture/data-format","label":"Data Format","docId":"architecture/data-format","unlisted":false}],"href":"/docs/category/architecture"},{"type":"category","label":"Ecosystem","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ecosystem","label":"Repositories","docId":"ecosystem/repositories","unlisted":false}],"href":"/docs/category/ecosystem"},{"type":"category","label":"Deployment","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/deployment/helm-charts","label":"Helm Charts","docId":"deployment/helm-charts","unlisted":false}],"href":"/docs/category/deployment"},{"type":"category","label":"Feature Nodes","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/feature-nodes/base-analytics","label":"Base Analytics Nodes","docId":"feature-nodes/base-analytics","unlisted":false},{"type":"link","href":"/docs/feature-nodes/ai-ml","label":"AI / ML Nodes","docId":"feature-nodes/ai-ml","unlisted":false},{"type":"link","href":"/docs/feature-nodes/cheminformatics","label":"Cheminformatics Nodes","docId":"feature-nodes/cheminformatics","unlisted":false},{"type":"link","href":"/docs/feature-nodes/knime","label":"KNIME Nodes","docId":"feature-nodes/knime","unlisted":false}],"href":"/docs/category/feature-nodes"},{"type":"category","label":"Contributing","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/contributing","label":"Scaffolding a New Feature Worker","docId":"contributing/feature-template","unlisted":false}],"href":"/docs/category/contributing"}]},"docs":{"architecture/data-format":{"id":"architecture/data-format","title":"Data Format","description":"All data passed between workflow nodes is Apache Parquet (Snappy-compressed, Avro schema DataRow) \u2014 not JSON. This keeps data columnar, compressed, and query-ready from the moment it leaves a node.","sidebar":"docsSidebar"},"architecture/node-model":{"id":"architecture/node-model","title":"Node Model & Feature Registration","description":"Every workflow node is defined inside a feature worker \u2014 an independent service (e.g. continuum-feature-base, continuum-feature-ai, continuum-feature-cheminformatics, or your own) built with the continuum-worker-springboot-starter. Workers register their nodes centrally so the orchestration service knows which worker to dispatch each node to.","sidebar":"docsSidebar"},"architecture/overview":{"id":"architecture/overview","title":"System Overview","description":"Continuum is split into a browser frontend, a core backend (API server + Temporal orchestration), and independent feature workers that provide the actual workflow nodes.","sidebar":"docsSidebar"},"contributing/feature-template":{"id":"contributing/feature-template","title":"Scaffolding a New Feature Worker","description":"Continuum is designed to be extended by adding new workers, not modifying existing ones \u2014 see Node Model & Feature Registration for why that\'s safe to do independently.","sidebar":"docsSidebar"},"deployment/helm-charts":{"id":"deployment/helm-charts","title":"Helm Charts","description":"continuum-charts publishes three Helm charts for deploying Continuum on Kubernetes, served as a standard Helm chart repository via GitHub Pages.","sidebar":"docsSidebar"},"ecosystem/repositories":{"id":"ecosystem/repositories","title":"Repositories","description":"Project Continuum is split across several focused repositories under the projectcontinuum-org GitHub organization \u2014 not a monorepo. Each one can be built and released independently.","sidebar":"docsSidebar"},"feature-nodes/ai-ml":{"id":"feature-nodes/ai-ml","title":"AI / ML Nodes","description":"continuum-feature-ai provides nodes for training and fine-tuning LLMs directly inside workflow graphs. Ships as a Spring Boot worker with an auto-managed Python virtual environment for ML execution.","sidebar":"docsSidebar"},"feature-nodes/base-analytics":{"id":"feature-nodes/base-analytics","title":"Base Analytics Nodes","description":"continuum-feature-base ships 16 production-ready nodes for data transformation, filtering, aggregation, REST integration, scripting, and anomaly detection.","sidebar":"docsSidebar"},"feature-nodes/cheminformatics":{"id":"feature-nodes/cheminformatics","title":"Cheminformatics Nodes","description":"continuum-feature-cheminformatics ships 38 production-grade cheminformatics nodes across 10 categories, powered by RDKit. Built for computational chemistry, medicinal chemistry, and drug discovery teams who need scalable, reproducible molecular processing pipelines \u2014 parse, standardize, fingerprint, filter, react, and visualize molecules at scale.","sidebar":"docsSidebar"},"feature-nodes/knime":{"id":"feature-nodes/knime","title":"KNIME Nodes","description":"continuum-feature-knime provides Continuum workflow executors for KNIME workflows (.knwf files), bridging KNIME\'s compatibility layer (continuum-knime-base in continuum-platform-core) with Continuum\'s execution model.","sidebar":"docsSidebar"},"getting-started/local-setup":{"id":"getting-started/local-setup","title":"Local Setup","description":"The continuum-local-setup repo gives you a single docker compose up that launches the complete Project Continuum stack \u2014 infrastructure services, platform backend, browser IDE, and feature workers \u2014 all wired together and ready to go.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Project Continuum is an open-source, browser-native visual workflow platform \u2014 inspired by KNIME, built for the cloud. You design workflows as a drag-and-drop graph of nodes, and the platform runs them durably: a crashed worker, a dead Kafka broker, or a dropped connection doesn\'t lose your progress.","sidebar":"docsSidebar"}}}}')}}]);